import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"SIMD与SIMT混合编程简介","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/SIMD_SIMT_hybrid_programming_intro"},{"text":"扩展语法","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/extended_syntax"},{"text":"核函数（Kernel）配置","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/kernel_function_config"}]},"headers":[],"relativePath":"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/kernel_function_config.md","filePath":"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/kernel_function_config.md","outlineHeaders":[{"level":2,"title":"核函数（Kernel）定义","slug":"核函数（Kernel）定义","link":"#核函数（Kernel）定义"},{"level":2,"title":"__launch_bounds__(N)","slug":"__launch_bounds__(N)","link":"#__launch_bounds__(N)"},{"level":2,"title":"<<<>>>调用","slug":"<<<>>>调用","link":"#<<<>>>调用"},{"level":2,"title":"asc_vf_call调用","slug":"asc_vf_call调用","link":"#asc_vf_call调用"}],"lastUpdated":1787813964000}'),t={name:"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/kernel_function_config.md"};function c(d,s,e,_,i,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>核函数（Kernel）配置</h1><h2 id="核函数（Kernel）定义">核函数（Kernel）定义<a class="header-anchor" href="#核函数（Kernel）定义">​</a></h2><p>核函数（Kernel）是SIMD与SIMT混合编程的Device侧入口函数，负责协调整个算子的执行流程，包括VF的调度和调用。vector计算单元的混合编程场景下，函数定义语法为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">kernel_name</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">type</span><span class="o">*</span><span class="w"> </span><span class="n">param1</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">type</span><span class="o">*</span><span class="w"> </span><span class="n">param2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>关键修饰符说明如下：</p><ul><li><code>__global__</code>：必需修饰符，作用为标识核函数（Kernel），表明可在Host侧通过&lt;&lt;&lt;...&gt;&gt;&gt;调用。</li><li><code>__vector__</code>：必需修饰符，作用为标识函数是在Device侧AIV核上执行。</li></ul><p>核函数（Kernel）定义有以下几个约束：</p><ul><li>返回值类型必须是void；</li><li>入参支持指针类型（需使用<code>__gm__</code>修饰）和Ascend C内置数据类型；</li><li>指针参数必须是指向Global Memory上的内存地址，使用<code>__gm__</code>修饰。</li></ul><h2 id="__launch_bounds__(N)">__launch_bounds__(N)<a class="header-anchor" href="#__launch_bounds__(N)">​</a></h2><p>在多线程并发执行时，每个线程使用较少的寄存器可以让单个线程块内启动更多的线程，从而提升性能。因此，编译器会采用启发式算法，将寄存器溢出（register spilling）和指令数量控制在最低水平，同时尽量减少寄存器的使用量。应用程序可以通过在<code>__global__</code>函数定义中使用<code>__launch_bounds__()</code>限定符来限制启动边界（launch bounds），提供附加信息辅助编译器优化这一过程，这属于可选配置。</p><p><code>__launch_bounds__(N)</code>：函数标记宏，在SIMT VF入口函数上可选配置，用于在编译期指定SIMT VF启动的最大线程数。若未配置<code>__launch_bounds__</code>，最大线程数默认为1024。参数N需要满足：</p><ul><li><p>N &gt;= dimx * dimy * dimz；dimx, dimy, dimz为表示线程的dim3结构体。</p></li><li><p>N的取值范围为1到2048。</p><p>最大线程数决定了每个线程可分配的寄存器数量，具体对应关系请见下表，寄存器用于存储线程中的局部变量，若局部变量的个数超出寄存器个数，容易出现寄存器溢出等问题。建议最大线程数与启动VF任务的dim3线程数保持一致。</p><p><strong>表1</strong> __launch_bounds__(N)与每个线程可用寄存器个数的关系</p><table><thead><tr><th>N</th><th>每个线程可用寄存器个数</th></tr></thead><tbody><tr><td>1025~2048</td><td>16</td></tr><tr><td>513~1024</td><td>32</td></tr><tr><td>257~512</td><td>64</td></tr><tr><td>1~256</td><td>127</td></tr></tbody></table></li></ul><h2 id="&lt;&lt;&lt;&gt;&gt;&gt;调用">&lt;&lt;&lt;&gt;&gt;&gt;调用<a class="header-anchor" href="#&lt;&lt;&lt;&gt;&gt;&gt;调用">​</a></h2><p>核函数（Kernel）的调用是通过&lt;&lt;&lt;...&gt;&gt;&gt;内核调用符在Host侧调用，语法如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">kernel_name</span><span class="o">&lt;&lt;&lt;</span><span class="n">block_num</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ub_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">args</span><span class="p">...);</span>
</code></pre></div><p>内核调用符内的配置参数说明如下：</p><table><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>约束</th></tr></thead><tbody><tr><td>block_num</td><td>uint32_t</td><td>设置核函数（Kernel）启用的核数</td><td>取值范围[1, 65535]</td></tr><tr><td>dyn_ub_size</td><td>uint32_t</td><td>指定动态内存大小，单位为字节</td><td>不超过最大可配置值：256KB - 8KB - 32KB - 静态内存</td></tr><tr><td>stream</td><td>aclrtStream</td><td>用于维护异步操作执行顺序</td><td>无</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>由于混合编程场景&lt;&lt;&lt;&gt;&gt;&gt;调用时，参数block_num的数据类型为uint32_t，因此SIMT架构中的gridDim是一维的，即：gridDim.x=block_num，gridDim.y和gridDim.z均为1。</p></div><h2 id="asc_vf_call调用">asc_vf_call调用<span id="asc-vf-call"></span><a class="header-anchor" href="#asc_vf_call调用">​</a></h2><p>在SIMD与SIMT混合编程场景，需使用asc_vf_call启动SIMT VF（Vector Function）子任务，通过参数配置，启动指定数目的线程，执行指定的SIMT VF函数。其函数原型如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">auto</span><span class="w"> </span><span class="n">funcPtr</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="p">...</span><span class="w"> </span><span class="n">Args</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_vf_call</span><span class="p">(</span><span class="n">dim3</span><span class="w"> </span><span class="n">threadNums</span><span class="p">,</span><span class="w"> </span><span class="n">Args</span><span class="w"> </span><span class="o">&amp;&amp;</span><span class="p">...</span><span class="n">args</span><span class="p">)</span>
</code></pre></div><p>其中模板参数为指定的SIMT VF函数名以及SIMT VF函数参数，具体描述如下：</p><p><strong>表2</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>funcPtr</td><td>用于指定SIMT入口核函数（Kernel）。</td></tr><tr><td>Args</td><td>定义可变参数，用于传递实参到SIMT入口核函数（Kernel）。</td></tr></tbody></table><p><strong>表3</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>threadNums</td><td>输入</td><td><a href="./builtin_data_types.html#dim3">dim3类型</a>，用于指定SIMT线程块内线程数量。线程总数为x * y * z，该值的大小必须小于等于2048，建议为32的倍数。</td></tr><tr><td>args</td><td>输入</td><td>可变参数，用于传递实参到SIMT入口核函数（Kernel）。</td></tr></tbody></table><p>以下示例展示了SIMD与SIMT混合编程场景下如何使用asc_vf_call调用__simt_vf__函数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;simt_api/common_functions.h&quot;</span>
<span class="n">__simt_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_simt</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src1</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// simt代码</span>
<span class="w">    </span><span class="kt">int</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src0</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">src1</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="p">}</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// asc_vf_call启动SIMT VF子任务，函数名为：add_simt，配置threadNums为dim3{1024, 1, 1}</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">add_simt</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dim3</span><span class="p">{</span><span class="mi">1024</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">},</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const g=a(t,[["render",c]]);export{h as __pageData,g as default};
